		// TODO Auto-generated method stub
		byte quantity = 5;
        short productCode = 1025;
        int price = 25000;
        long barcode = 8901234567890L;
        float weight = 1.5f;
        double discount = 10.50;
        char category = 'E';
        boolean available = true;
        String productName = "Laptop";

        System.out.println("Product Name --> " + productName);
